SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "abstraction"@en "algebraic data type"@en "applicative functor"@en "argument"@en "buffer overflow"@en "class"@en "closure"@en "code generation"@en "concurrency"@en "constant"@en "constructor"@en "context switch"@en "coroutine"@en "currying"@en "declarative programming"@en "destructor"@en "dynamic typing"@en "eager evaluation"@en "encapsulation"@en "exception"@en "exception handling"@en "functional programming"@en "functor"@en "garbage collection"@en "generic programming"@en "higher-order function"@en "identifier"@en "immutability"@en "imperative programming"@en "inheritance"@en "instance"@en "interface"@en "intermediate representation"@en "kernel"@en "lambda expression"@en "lazy evaluation"@en "logic programming"@en "memory allocation"@en "memory leak"@en "method"@en "monad"@en "namespace"@en "null pointer"@en "object"@en "object-oriented programming"@en "operating system"@en "overloading"@en "overriding"@en "parallelism"@en "parameter"@en "parse tree"@en "partial application"@en "pattern matching"@en "pointer"@en "polymorphism"@en "process"@en "product type"@en "pure function"@en "reference"@en "referential transparency"@en "return value"@en "scheduler"@en "scope"@en "segmentation fault"@en "side effect"@en "stack overflow"@en "static analysis"@en "static typing"@en "strong typing"@en "sum type"@en "system call"@en "thread"@en "token"@en "type checking"@en "type inference"@en "type safety"@en "type system"@en "undefined behavior"@en "variable"@en "weak typing"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
